// news-image-20261125 entry: copies pre-rendered PNG to output directory
// The PNG is generated by render_news.py (deterministic, 1024x1024)

import { copyFileSync } from 'node:fs';
import { join } from 'node:path';

const OUT_DIR = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';
const OUT_PATH = join(OUT_DIR, 'entry.png');
const SRC_PATH = join(__dirname, 'entry.png');

function main(): void {
  copyFileSync(SRC_PATH, OUT_PATH);
  console.log(`Copied ${SRC_PATH} -> ${OUT_PATH}`);
}

main();